import urllib.parse

def parse_query_string(query: str) -> dict[str, list[str]]:
    if query.startswith('?'):
        query = query[1:]
    pairs = query.split('&')
    result = {}
    for pair in pairs:
        if pair:
            key, value = pair.split('=', 1) if '=' in pair else (pair, '')
            key = urllib.parse.unquote(key.replace('+', ' '))
            value = urllib.parse.unquote(value.replace('+', ' '))
            if key in result:
                result[key].append(value)
            else:
                result[key] = [value]
    return result

